import copy,json,work

def ev(req,evi,pol):
    before=copy.deepcopy((req,evi,pol)); out=work.evaluate(req,evi,pol); assert (req,evi,pol)==before; assert set(out)=={'status','value','sources','unknowns'}; return out

p={'required_conditions':['x'],'require_verified':False}
cases=[
 ({'claim':'c','conditions':{}},[{'source':'z','claim':'c','value':1,'conditions':{}}],p,{'status':'unknown','value':None,'sources':[],'unknowns':['x']}),
 ({'claim':'c','conditions':{'x':1}},[],p,{'status':'unknown','value':None,'sources':[],'unknowns':['no matching evidence']}),
 ({'claim':'c','conditions':{'x':1}},[{'source':'b','claim':'c','value':{'q':2,'p':1},'conditions':{'x':1}},{'source':'a','claim':'c','value':{'p':1,'q':2},'conditions':{'x':1}}],p,{'status':'supported','value':{'q':2,'p':1},'sources':['a','b'],'unknowns':[]}),
 ({'claim':'c','conditions':{'x':1}},[{'source':'a','claim':'c','value':9,'conditions':{'x':1}},{'source':'b','claim':'c','value':8,'conditions':{'x':1}},{'source':'c','claim':'c','value':8,'conditions':{'x':1}}],p,{'status':'conflict','value':None,'sources':['a','b','c'],'unknowns':['source disagreement']}),
 ({'claim':'c','conditions':{'x':1}},[{'source':'old','claim':'c','value':1,'conditions':{'x':1}},{'source':'new','claim':'c','value':2,'conditions':{'x':1},'supersedes':['old']},{'source':'bad','claim':'other','value':3,'conditions':{'x':1},'supersedes':['new']}],p,{'status':'supported','value':2,'sources':['new'],'unknowns':[]}),
 ({'claim':'c','conditions':{'x':1}},[{'source':'n','claim':'c','value':None,'conditions':{'x':1}}],p,{'status':'supported','value':None,'sources':['n'],'unknowns':[]}),
]
for req,evi,pol,want in cases: assert ev(req,evi,pol)==want,(ev(req,evi,pol),want)
strict={'required_conditions':['x'],'require_verified':True}
assert ev({'claim':'c','conditions':{'x':1}},[{'source':'u','claim':'c','value':4,'conditions':{'x':1},'verified':False}],strict)=={'status':'unknown','value':None,'sources':[],'unknowns':['no matching evidence']}
# absent calibration remains absent rather than becoming numeric zero
assert ev({'claim':'calibration','conditions':{'x':1}},[],p)['value'] is None
print('boundary checks passed')
